function ensureTextureCoordinates(mesh){ const geometry=mesh.geometry; if(geometry.attributes.uv)return false; const positions=geometry.attributes.position; if(!positions)return false; if(!geometry.attributes.normal)geometry.computeVertexNormals(); const normals=geometry.attributes.normal; geometry.computeBoundingBox(); const bounds=geometry.boundingBox, min=bounds.min, max=bounds.max; const axisSpan={x:Math.max(max.x-min.x,0.000001),y:Math.max(max.y-min.y,0.000001),z:Math.max(max.z-min.z,0.000001)}; const uv=[]; for(let index=0;index<positions.count;index++){ const x=positions.getX(index), y=positions.getY(index), z=positions.getZ(index), nx=Math.abs(normals.getX(index)), ny=Math.abs(normals.getY(index)), nz=Math.abs(normals.getZ(index)); let u,v,minU,minV,tileSize; if(nx>=ny&&nx>=nz){u=z;v=y;minU=min.z;minV=min.y;tileSize=Math.max(axisSpan.z,axisSpan.y);} else if(ny>=nx&&ny>=nz){u=x;v=z;minU=min.x;minV=min.z;tileSize=Math.max(axisSpan.x,axisSpan.z);} else {u=x;v=y;minU=min.x;minV=min.y;tileSize=Math.max(axisSpan.x,axisSpan.y);} uv.push((u-minU)/tileSize,1-(v-minV)/tileSize); } geometry.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2)); geometry.attributes.uv.needsUpdate=true; mesh.userData.generatedUv=true; return true; }
