function prepareTexture(texture){ texture.colorSpace=THREE.SRGBColorSpace; texture.flipY=false; texture.wrapS=THREE.RepeatWrapping; texture.wrapT=THREE.RepeatWrapping; texture.anisotropy=renderer.capabilities.getMaxAnisotropy(); texture.needsUpdate=true; return texture; }
function applyTexture(texture,url){ let applied=0, autoMapped=0; selectedParts.forEach(part=>{ if(!part.geometry?.attributes?.uv){ if(!ensureTextureCoordinates(part))return; autoMapped++; } const materials=Array.isArray(part.material)?part.material:[part.material]; materials.forEach(material=>{ const materialTexture=texture.clone(); materialTexture.needsUpdate=true; material.map=materialTexture; material.userData.appliedTextureUrl=url; material.needsUpdate=true; applied++; }); }); return {applied,autoMapped}; }
window.applyModelTexture=(url,name)=>{ if(!selectedParts.length){ toast('Select one or more model parts first.'); return; } new THREE.TextureLoader().load(url,t=>{ const result=applyTexture(prepareTexture(t),url); materialsPanel.querySelector('#texture-status').textContent=result.applied?'Applied: '+name+(result.autoMapped?' · Auto-mapped':''):'Texture could not be mapped'; }, undefined, error=>{ materialsPanel.querySelector('#texture-status').textContent='Texture could not be loaded'; console.error('Texture could not be loaded',error); }); };
materialsPanel.querySelector('#apply-texture').onclick=()=>{ if(pendingTexture)window.applyModelTexture(pendingTexture.url,pendingTexture.name); };
function applyVariant(variant){ const parts=variant?.configuration?.parts||{}; Object.entries(parts).forEach(([key,state])=>{ const part=modelParts.find(candidate=>candidate.userData.stableId===key)||modelParts[Number(key)]; if(!part)return; const materials=Array.isArray(part.material)?part.material:[part.material]; materials.forEach(material=>{ if(state.color&&material.color)material.color.set(state.color); if(state.texture&&part.geometry?.attributes?.uv)new THREE.TextureLoader().load(state.texture,texture=>{ prepareTexture(texture); material.map=texture; material.userData.appliedTextureUrl=state.texture; material.needsUpdate=true; }); }); }); variantPanel.querySelector('#variant-status').textContent='Applied'; }
variantPanel.querySelector('#apply-variant').onclick=()=>{ if(pendingVariant)applyVariant(pendingVariant); };
materialsPanel.querySelector('#texture-search').oninput=event=>{ const query=event.target.value.toLowerCase(); textureLibraryEl.querySelectorAll('.texture-option').forEach(button=>button.classList.toggle('hidden',!button.textContent.toLowerCase().includes(query))); };
materialsPanel.querySelector('#texture-scale').oninput=event=>{ const scale=Number(event.target.value); selectedMaterials().forEach(material=>{ if(material.map)material.map.repeat.set(scale,scale); }); };
materialsPanel.querySelector('#clear-applied-texture').onclick=()=>{ selectedMaterials().forEach(material=>{ material.map=null; material.needsUpdate=true; }); materialsPanel.querySelector('#texture-status').textContent='Texture cleared'; };
materialsPanel.querySelector('#reset-appearance').onclick=()=>{ modelParts.forEach(part=>{ const materials=Array.isArray(part.material)?part.material:[part.material]; materials.forEach(material=>{ if(material.userData.originalColor)material.color.copy(material.userData.originalColor); material.map=material.userData.originalMap||null; material.needsUpdate=true; }); }); pendingTexture=null; materialsPanel.querySelector('#texture-status').textContent='Appearance reset'; };
new GLTFLoader().load(@json($modelUrl), async gltf=>{ model=gltf.scene; const box=new THREE.Box3().setFromObject(model), size=box.getSize(new THREE.Vector3()); modelCenter.copy(box.getCenter(new THREE.Vector3())); modelScale=2.5/Math.max(size.x,size.y,size.z); model.scale.setScalar(modelScale); model.position.sub(modelCenter.clone().multiplyScalar(modelScale)); scene.add(model); if(cameraSettings?.position){ const toViewerSpace=v=>new THREE.Vector3(v?.x??0,v?.y??0,v?.z??0).sub(modelCenter).multiplyScalar(modelScale); camera.position.copy(toViewerSpace(cameraSettings.position)); if(cameraSettings.target)controls.target.copy(toViewerSpace(cameraSettings.target)); controls.update(); originalCamera.copy(camera.position); originalTarget.copy(controls.target); } listParts(); captureOriginalAppearance(); addSelectionControls(); const hashConfig=window.location.hash.startsWith('#config=')?decodeConfiguration(window.location.hash.slice(8)):null; const localConfig=JSON.parse(localStorage.getItem('model-config-{{ $item->slug }}')||'null'); const queryToken=new URLSearchParams(window.location.search).get('configuration'); const savedConfig=queryToken?await loadServerConfiguration(queryToken):null; restoreConfiguration(savedConfig?.configuration||hashConfig||localConfig); }, progress=>{ if(progress.lengthComputable){ const percentEl=document.querySelector('#loading-percent'); if(percentEl)percentEl.textContent=' '+Math.round(progress.loaded/progress.total*100)+'%'; } }, e=>{ partsEl.innerHTML='<p class="px-3 py-2 text-sm text-rose-300">Could not load this GLB file.</p>'; loadingOverlay.querySelector('p').textContent='Could not load this model.'; console.error(e); });
stage.addEventListener('pointerdown', e=>{ if(!model||e.target.closest('button'))return; const rect=renderer.domElement.getBoundingClientRect(); pointer.x=((e.clientX-rect.left)/rect.width)*2-1; pointer.y=-((e.clientY-rect.top)/rect.height)*2+1; raycaster.setFromCamera(pointer,camera); const hit=raycaster.intersectObject(model,true)[0]; if(hit){ const index=modelParts.indexOf(hit.object); select(hit.object,partsEl.querySelector(`[data-part="${index}"]`)); } else { deselectAll(); } });
addEventListener('keydown', event=>{ if(event.target.closest('input,textarea,select'))return; if(event.key==='Escape'){ deselectAll(); toggleShortcuts(false); toggleEmbed(false); } else if(event.key==='?'){ toggleShortcuts(true); } else if(event.key==='r'||event.key==='R'){ document.querySelector('#reset').click(); } else if(event.key==='f'||event.key==='F'){ document.querySelector('#fullscreen').click(); } else if(event.key==='w'||event.key==='W'){ wireframeTool.click(); } else if(event.key==='e'||event.key==='E'){ viewerTools.querySelector('#explode-model').click(); } else if(event.key==='a'||event.key==='A'){ viewerTools.querySelector('#auto-rotate').click(); } else if(event.key==='i'||event.key==='I'){ viewerTools.querySelector('#isolate-part').click(); } });
stage.addEventListener('click', e=>{ if(!measureMode||!model||e.target.closest('button'))return; const rect=renderer.domElement.getBoundingClientRect(); pointer.x=((e.clientX-rect.left)/rect.width)*2-1; pointer.y=-((e.clientY-rect.top)/rect.height)*2+1; raycaster.setFromCamera(pointer,camera); const hit=raycaster.intersectObject(model,true)[0]; if(!hit)return; if(measurePoints.length===2){ measurePoints=[]; measureGroup.clear(); } measurePoints.push(hit.point.clone()); if(measurePoints.length===2){ const distance=measurePoints[0].distanceTo(measurePoints[1]); const geometry=new THREE.BufferGeometry().setFromPoints(measurePoints); const line=new THREE.Line(geometry,new THREE.LineBasicMaterial({color:0xfbbf24,depthTest:false})); line.renderOrder=20; measureGroup.add(line); measureLabel.textContent='Distance: '+distance.toFixed(3)+' model units'; measureLabel.classList.remove('hidden'); } });
function updateMeasurementLabel(){ if(measurePoints.length!==2)return; const midpoint=measurePoints[0].clone().lerp(measurePoints[1],.5).project(camera); const rect=stage.getBoundingClientRect(); measureLabel.style.left=((midpoint.x+1)/2*rect.width)+'px'; measureLabel.style.top=((-midpoint.y+1)/2*rect.height)+'px'; }
viewerTools.querySelector('#measure-model').onclick=event=>{ measureMode=!measureMode; event.currentTarget.classList.toggle('tool-active-amber',measureMode); const label=measureMode?'Click two points':'Measure'; event.currentTarget.innerHTML=`<span class="sm:hidden">↔</span><span class="hidden sm:inline">${label}</span>`; if(!measureMode){ measurePoints=[]; measureGroup.clear(); measureLabel.classList.add('hidden'); } };
quoteButton.onclick=()=>{ quoteModal.classList.remove('hidden'); quoteModal.classList.add('flex'); };
quoteModal.querySelector('.close-quote').onclick=()=>{ quoteModal.classList.add('hidden'); quoteModal.classList.remove('flex'); };
quoteModal.querySelector('form').onsubmit=async event=>{ event.preventDefault(); const form=event.currentTarget, error=quoteModal.querySelector('.quote-error'), submit=form.querySelector('button[type="submit"]'); submit.disabled=true; error.classList.add('hidden'); try { const response=await fetch(@json(route('items.quote-requests.store',$item->slug)),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':@json(csrf_token())},body:JSON.stringify({name:form.name.value,email:form.email.value,company:form.company.value,message:form.message.value,configuration:configurationState()})}); if(!response.ok)throw new Error('Request could not be sent'); form.innerHTML='<div class="py-8 text-center"><div class="text-4xl text-emerald-300">✓</div><h2 class="mt-3 text-xl font-medium text-white">Request received</h2><p class="mt-2 text-sm text-slate-400">Our team will review your configuration and contact you soon.</p></div>'; } catch(exception) { error.textContent='Please check your details and try again.'; error.classList.remove('hidden'); submit.disabled=false; } };
document.querySelector('#apply-color').onclick=()=>{ const color=document.querySelector('#color').value; selectedMaterials().forEach(material=>{ material.color?.set(color); material.userData.appliedColor=color; material.needsUpdate=true; }); document.querySelector('#texture-status').textContent='Color applied: '+color; };
document.querySelector('#clear-texture')?.addEventListener('click',()=>{ selectedMaterials().forEach(material=>{material.map=null;material.needsUpdate=true;}); document.querySelector('#clear-texture')?.classList.add('hidden'); });
document.querySelector('#reset').onclick=()=>{ camera.position.copy(originalCamera); controls.target.copy(originalTarget); controls.update(); isolated=false; exploded=false; modelParts.forEach(part=>part.visible=true); setExplode(0); viewerTools.querySelector('#isolate-part').classList.remove('tool-active'); setIsolateLabel(viewerTools.querySelector('#isolate-part'),'Isolate'); viewerTools.querySelector('#explode-model').classList.remove('tool-active'); };
function configurationState(){ return { version:2, item:'{{ $item->slug }}', parts:modelParts.map((part,index)=>({ id:part.userData.stableId||`mesh-${index}`, name:part.userData.displayName||`Part ${index+1}`, index, visible:part.visible, materials:(Array.isArray(part.material)?part.material:[part.material]).map(material=>({ color:material.color?.getHexString(), texture:material.userData.appliedTextureUrl||null })) })) }; }
function encodeConfiguration(state){ return btoa(unescape(encodeURIComponent(JSON.stringify(state)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); }
function decodeConfiguration(value){ try { const padded=value.replace(/-/g,'+').replace(/_/g,'/')+'==='.slice((value.length+3)%4); return JSON.parse(decodeURIComponent(escape(atob(padded)))); } catch(error) { console.error('Invalid model configuration',error); return null; } }
async function saveConfiguration(){ const state=configurationState(); localStorage.setItem('model-config-{{ $item->slug }}',JSON.stringify(state)); const response=await fetch(@json(route('items.configurations.store',$item->slug)),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':@json(csrf_token())},body:JSON.stringify({name:'My configuration',configuration:state})}); if(!response.ok)throw new Error('Configuration could not be saved'); const data=await response.json(); const button=document.querySelector('#save-config'); const setLabel=text=>button.innerHTML=`<span class="sm:hidden">▣</span><span class="hidden sm:inline">${text}</span>`; setLabel('Configuration saved'); setTimeout(()=>setLabel('Save configuration'),1800); return data; }
async function loadServerConfiguration(token){ try { const response=await fetch(@json(route('items.configurations.show',[$item->slug,'CONFIGURATION_TOKEN'])).replace('CONFIGURATION_TOKEN',encodeURIComponent(token)),{headers:{'Accept':'application/json'}}); return response.ok?await response.json():null; } catch(error) { console.error('Configuration could not be loaded',error); return null; } }
async function shareConfiguration(){ try { const data=await saveConfiguration(); await navigator.clipboard.writeText(data.url); const button=document.querySelector('#share-config'); const setLabel=text=>button.innerHTML=`<span class="sm:hidden">↗</span><span class="hidden sm:inline">${text}</span>`; setLabel('Link copied'); setTimeout(()=>setLabel('Share configuration'),1800); } catch(error) { const url=new URL(window.location.href); url.hash='config='+encodeConfiguration(configurationState()); window.prompt('Copy this configuration link:',url.toString()); } }
function restoreConfiguration(state){ if(!state?.parts)return; state.parts.forEach(saved=>{ const part=saved.id?modelParts.find(candidate=>candidate.userData.stableId===saved.id):modelParts[saved.index]; if(!part)return; part.visible=saved.visible!==false; const materials=Array.isArray(part.material)?part.material:[part.material]; saved.materials?.forEach((materialState,index)=>{ const material=materials[index]; if(!material)return; if(materialState.color&&material.color)material.color.set('#'+materialState.color); if(materialState.texture&&part.geometry?.attributes?.uv)new THREE.TextureLoader().load(materialState.texture,texture=>{ prepareTexture(texture); material.map=texture; material.userData.appliedTextureUrl=materialState.texture; material.needsUpdate=true; }); }); }); }
function setExplode(amount){ if(!model)return; modelParts.forEach(part=>{ part.position.copy(part.userData.originalPosition); if(amount){ const direction=part.userData.explodeDirection||new THREE.Vector3((part.position.x||0)+.1,(part.position.y||0)+.1,(part.position.z||0)+.1).normalize(); part.position.addScaledVector(direction,amount); } }); }
viewerTools.querySelector('#auto-rotate').onclick=event=>{ autoRotate=!autoRotate; event.currentTarget.classList.toggle('tool-active',autoRotate); };
function setIsolateLabel(button,text){ button.innerHTML=`<span class="sm:hidden">◎</span><span class="hidden sm:inline">${text}</span>`; }
viewerTools.querySelector('#isolate-part').onclick=event=>{ if(!selectedParts.length){ toast('Select a model part first.'); return; } isolated=!isolated; modelParts.forEach(part=>part.visible=!isolated||selectedParts.includes(part)); event.currentTarget.classList.toggle('tool-active',isolated); setIsolateLabel(event.currentTarget,isolated?'Show all parts':'Isolate selected'); };
viewerTools.querySelector('#explode-model').onclick=event=>{ exploded=!exploded; setExplode(exploded ? .45 : 0); event.currentTarget.classList.toggle('tool-active',exploded); };
viewerTools.querySelector('#save-config').onclick=saveConfiguration;
viewerTools.querySelector('#share-config').onclick=shareConfiguration;
viewerTools.querySelector('#set-default-view')?.addEventListener('click',async event=>{ const button=event.currentTarget; const toModelSpace=v=>v.clone().divideScalar(modelScale).add(modelCenter); const position=toModelSpace(camera.position); const target=toModelSpace(controls.target); const original=button.innerHTML; try { const response=await fetch(@json(route('items.camera-settings.update',$item->slug)),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':@json(csrf_token())},body:JSON.stringify({position:{x:position.x,y:position.y,z:position.z},target:{x:target.x,y:target.y,z:target.z},vertical_fov_degrees:camera.fov,near:camera.near,far:camera.far})}); if(!response.ok)throw new Error('Request failed'); button.innerHTML='<span class="sm:hidden">◈</span><span class="hidden sm:inline">Saved!</span>'; originalCamera.copy(camera.position); originalTarget.copy(controls.target); } catch(error) { button.innerHTML='<span class="sm:hidden">◈</span><span class="hidden sm:inline">Failed, try again</span>'; } finally { setTimeout(()=>button.innerHTML=original,2000); } });
document.querySelector("#fullscreen").onclick=()=>{ document.fullscreenElement ? document.exitFullscreen() : stage.requestFullscreen?.(); }; document.querySelector("#share")?.addEventListener('click',async()=>{ try { if(navigator.share){ await navigator.share({title:document.title,url:window.location.href}); } else { await navigator.clipboard.writeText(window.location.href); const button=document.querySelector("#share"); button.textContent="Link copied"; setTimeout(()=>button.textContent="Share",1800); } } catch(error) { if(error.name !== "AbortError") console.error(error); } }); function download(type){ const link=document.createElement('a'); link.download='{{ $item->slug }}.'+(type==='image/jpeg'?'jpg':'png'); link.href=renderer.domElement.toDataURL(type,.92); link.click(); } document.querySelector('#png').onclick=()=>download('image/png'); document.querySelector('#jpeg').onclick=()=>download('image/jpeg');
</script>@if($tourEnabled)<script src="https://unpkg.com/driver.js@1.8.0/dist/driver.js.iife.js"></script><script>
// Guided tour of the configurator (parts, color, textures, variants, tools).
// Waits for DOMContentLoaded so it runs after the deferred module script
// above has built the materials/variants panels it needs to target.
// `tourFrequency` is a System Settings choice: 'once' (default) auto-starts
// only the first time this browser ever opens a model page; 'always'
// auto-starts on every visit regardless of the "seen it" flag.
const tourFrequency = @json($tourFrequency);
document.addEventListener('DOMContentLoaded', () => {
    const switchTab = (name) => document.querySelector(`.sidebar-tab[data-tab="${name}"]`)?.click();

    const steps = [
        {
            popover: {
                title: 'Welcome to the 3D configurator',
                description: 'Drag to orbit, scroll to zoom, and click any part of the model to select it. Here\'s a quick tour of everything you can do.',
            },
        },
        {
            element: '#parts',
            popover: {
                title: 'Select a part',
                description: 'Every part of the model is listed here. Click one (or click it directly on the model) — whatever\'s selected is what color and texture changes apply to.',
                side: 'left',
            },
        },
        {
            element: '#color-control',
            popover: {
                title: 'Change color',
                description: 'Pick a color and hit "Apply color" to recolor the selected part instantly.',
                side: 'left',
            },
        },
        {
            element: '#sidebar-tabs',
            popover: {
                title: 'Materials & variants',
                description: 'Switch tabs to browse textures or pre-built variants for this model.',
                side: 'bottom',
            },
        },
        {
            element: '#texture-library',
            popover: {
                title: 'Apply a texture',
                description: 'Browse the texture library, click one to select it, then "Apply texture" to map it onto the selected part. Use the scale slider to adjust tiling, or "Clear" to remove it.',
                side: 'left',
            },
            onHighlightStarted: () => switchTab('materials'),
        },
        {
            element: '#variant-panel-anchor',
            popover: {
                title: 'Product variants',
                description: 'If this model has pre-configured variants (e.g. different finishes), pick one from the list and apply it in a single click.',
                side: 'left',
            },
            onHighlightStarted: () => switchTab('variants'),
        },
        {
            element: '#viewer-tools',
            popover: {
                title: 'Viewer tools',
                description: 'Auto-rotate the model, isolate the selected part, explode the view to see how parts fit together, measure distances, or save/share your current configuration as a link.',
                side: 'left',
            },
            onHighlightStarted: () => switchTab('parts'),
        },
        {
            element: '#viewer-toolbar',
            popover: {
                title: 'Reset & export',
                description: 'Reset the camera, go fullscreen, share the page, export a PNG/JPEG snapshot, or download the source GLB file.',
                side: 'top',
            },
        },
        {
            element: '.hotspot-marker',
            popover: {
                title: 'Hotspots',
                description: 'Numbered markers on the model reveal extra details — click one to read more.',
                side: 'top',
            },
        },
        {
            element: '#ar-button',
            popover: {
                title: 'View in AR',
                description: 'On a supported phone or headset, place the model in your own space with augmented reality.',
                side: 'top',
            },
        },
        {
            element: '#like-button',
            popover: {
                title: 'Like this model',
                description: 'Found it useful? Give it a like.',
                side: 'bottom',
            },
        },
        {
            element: '#shortcuts-help',
            popover: {
                title: 'Keyboard shortcuts',
                description: 'Click here anytime to see the full list of keyboard shortcuts.',
                side: 'top',
            },
        },
        {
            popover: {
                title: "You're all set!",
                description: 'Replay this tour anytime with the "Take a tour" button at the top of the page.',
            },
        },
    ].filter((step) => !step.element || document.querySelector(step.element));

    const tour = window.driver.js.driver({
        showProgress: true,
        allowClose: true,
        overlayOpacity: 0.6,
        nextBtnText: 'Next',
        prevBtnText: 'Back',
        doneBtnText: 'Done',
        progressText: '@{{current}} of @{{total}}',
        steps,
        onDestroyed: () => { try { localStorage.setItem('model-viewer-tour-completed', '1'); } catch (e) {} },
    });

    document.querySelector('#start-tour')?.addEventListener('click', () => tour.drive());

    let alreadySeen = false;
    if (tourFrequency !== 'always') {
        try { alreadySeen = localStorage.getItem('model-viewer-tour-completed') === '1'; } catch (e) {}
    }
    if (!alreadySeen && steps.length > 0 && !@json($embed)) {
        window.setTimeout(() => tour.drive(), 600);
    }
});
</script>@endif</body></html>
